<script setup lang="ts">import { onMounted, reactive, ref } from 'vue';import { api } from '../api';import type { User } from '../types';import { ElMessage } from 'element-plus';const rows=ref<User[]>([]),dialog=ref(false),form=reactive<any>({username:'',password:'',displayName:'',roleCode:'MEMBER'});async function load(){rows.value=await api.users()}onMounted(load);function create(){Object.assign(form,{username:'',password:'',displayName:'',roleCode:'MEMBER'});dialog.value=true}async function save(){await api.createUser(form);dialog.value=false;ElMessage.success('用户已创建');load()}</script>
<template><div class="page"><div class="page-header"><h1 class="page-title">人员管理</h1><el-button type="primary" @click="create">新增用户</el-button></div><section class="card"><el-table :data="rows"><el-table-column prop="username" label="账号"/><el-table-column prop="displayName" label="姓名"/><el-table-column prop="roleCode" label="角色"/><el-table-column prop="enabled" label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'禁用'}}</el-tag></template></el-table-column></el-table></section><el-dialog v-model="dialog" title="新增用户"><el-form label-width="80"><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.displayName"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password"/></el-form-item><el-form-item label="角色"><el-select v-model="form.roleCode"><el-option label="管理员" value="ADMIN"/><el-option label="项目经理" value="PM"/><el-option label="成员" value="MEMBER"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>

